# -*- coding: utf-8 -*-
"""ҚМЖ v2 pilot: three lessons of different types. python3 pilot.py OUTDIR"""
import json, os, sys, subprocess, qrcode
sys.path.insert(0, os.path.dirname(__file__))
import figs2

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
IMG = os.path.join(ROOT, 'img', 'v2')
OUT = sys.argv[1] if len(sys.argv) > 1 else os.path.join(ROOT, 'v2')
os.makedirs(IMG, exist_ok=True); os.makedirs(OUT, exist_ok=True)
SZ = {}
for k, f in figs2.ALL.items():
    SZ[k] = f(os.path.join(IMG, k + '.png'))


def img(k, cap):
    w, h = SZ[k]
    return [f'img:{k}.png:{w}:{h}', f'> *{cap}*']


def qr(name, url):
    p = os.path.join(IMG, name)
    if not os.path.exists(p): qrcode.make(url, box_size=6, border=2).save(p)
    return name


PH = 'https://phet.colorado.edu/en/simulations/'
COMMON_RES = [('Bilimland', 'видеосабақтар', 'https://bilimland.kz/', 'qr_bilimland.png'), ('OPIQ', 'цифрлық оқулық', 'https://www.opiq.kz/', 'qr_opiq.png')]


def res_section(items):
    return {'title': 'Сандық ресурстар (сілтемелер тексерілген, QR-кодпен ашылады)', 'type': 'qr',
            'items': [(a, b, u, qr(f, u)) for a, b, u, f in items]}


def base(no, grade, bolim, topic, date, codes, smart, extra, stages, sections):
    tail = []
    for sec in list(sections):
        if 'tail' in sec: sections.remove(sec)  # саралау кестесі қажет емес; ЕББҚ сабақ кезеңдерінің ішінде
    return {'tail': tail, 'no': no, 'zam': '____________________', 'teacher': '', 'date': date, 'grade': grade, 'bolim': bolim, 'topic': topic,
            'objectives': codes, 'smart': [f'- {x}' for x in smart], 'extraHeader': extra, 'stages': stages, 'sections': sections}


